grid=[[0]*18 for _ in range(17)]; grid[0]=[9,5,3,4]+[0]*14; grid[16]=[2,1,3,8]+[0]*10+[4,5,6,7]
# set seed markers, stamps preserving markers
sequences={9:[9,5,3,4],8:[2,1,3,8],1:[2,1,3,8],2:[2,1,3,8],7:[4,5,6,7],6:[4,5,6,7]}
for r,c,v in [(1,11,8),(3,3,9),(5,13,6),(9,7,1),(11,13,2),(13,4,7)]:
 s=sequences[v]; i=s.index(v); start=c-i
 for j,val in enumerate(s):
  cc=start+j
  if 0<=cc<18: grid[r][cc]=val
[(len(row),row) for row in grid]
